#include <sstream>
#include "mpp/resource-parsers/DocumentWriter.h"
#include "mpp/resource-parsers/SceneSerializer.h"
#include "mpp/resource-parsers/StructuredDataWriteNode.h"
namespace mpp::resource_parsers { namespace { std::string v(glm::vec3 const&x){std::ostringstream s;s<<x.x<<' '<<x.y<<' '<<x.z;return s.str();} char const* source(SceneModelSource x){switch(x){case SceneModelSource::MppModel:return "mppmodel";case SceneModelSource::Box:return "box";case SceneModelSource::Cylinder:return "cylinder";case SceneModelSource::Grid:return "grid";default:return "sphere";}} } void SceneSerializer::toFile(SceneDocument const&d,std::string const&f){StructuredDataWriteNode w("Scene");auto r=&w;r->createChild("version")->setValue(d.version);r->createChild("name")->setValue(d.name);r->createChild("environmentBinding")->setValue(d.environmentBinding);auto c=r->createChild("Camera");c->createChild("position")->setValue(v(d.camera.position));c->createChild("target")->setValue(v(d.camera.target));c->createChild("fov")->setValue(d.camera.fov);c->createChild("near")->setValue(d.camera.nearPlane);c->createChild("far")->setValue(d.camera.farPlane);auto declaredLayers=r->createChild("Layers");for(auto const&l:d.layers)declaredLayers->createChild("Layer")->setValue(l);auto ms=r->createChild("Models");for(auto const&m:d.models){auto n=ms->createChild("Model");n->createChild("id")->setValue(m.id);n->createChild("source")->setValue(std::string(source(m.source)));if(!m.file.empty())n->createChild("file")->setValue(m.file);if(m.source!=SceneModelSource::MppModel){auto p=n->createChild("Primitive");p->createChild("width")->setValue(m.primitive.width);p->createChild("height")->setValue(m.primitive.height);p->createChild("depth")->setValue(m.primitive.depth);p->createChild("radius")->setValue(m.primitive.radius);p->createChild("topRadius")->setValue(m.primitive.topRadius);p->createChild("resolution")->setValue(m.primitive.resolution);p->createChild("segmentsX")->setValue(m.primitive.segmentsX);p->createChild("segmentsZ")->setValue(m.primitive.segmentsZ);p->createChild("textureRepeatU")->setValue(m.primitive.textureRepeatU);p->createChild("textureRepeatV")->setValue(m.primitive.textureRepeatV);}n->createChild("translation")->setValue(v(m.translation));n->createChild("rotation")->setValue(v(m.rotationDegrees));n->createChild("scale")->setValue(v(m.scale));n->createChild("materialBinding")->setValue(m.materialBinding);n->createChild("visible")->setValue(m.visible);n->createChild("shadowCaster")->setValue(m.shadowCaster);auto ls=n->createChild("Layers");for(auto const&l:m.layers)ls->createChild("Layer")->setValue(l);}auto lights=r->createChild("Lights");for(auto const&l:d.lights){auto n=lights->createChild("Light");n->createChild("id")->setValue(l.id);n->createChild("type")->setValue(std::string(l.type==SceneLightType::Point?"point":"directional"));n->createChild("colour")->setValue(v(l.colour));n->createChild("intensity")->setValue(l.intensity);n->createChild("position")->setValue(v(l.position));n->createChild("direction")->setValue(v(l.direction));n->createChild("range")->setValue(l.range);n->createChild("castsShadows")->setValue(l.castsShadows);}auto effects=r->createChild("ParticleEffects");for(auto const&e:d.particleEffects){auto n=effects->createChild("ParticleEffect");n->createChild("id")->setValue(e.id);n->createChild("effect")->setValue(e.effect);n->createChild("translation")->setValue(v(e.translation));n->createChild("rotation")->setValue(v(e.rotationDegrees));n->createChild("scale")->setValue(v(e.scale));n->createChild("visible")->setValue(e.visible);}detail::writeDocument(w.toStructuredData(),f);} }
